Given a binary tree, the task is to find the postorder traversal of the tree without using recursion.Examples:Input: Output: 4 5 2 3 1Explanation: Postorder traversal (Left->Right->Root) of the tree is 4 5 2 3 1.Input: Output: 10 7 1 6 10 6 5 8 Explanation: Postorder traversal (Left->Right->Root) of the tree is 10 7 1 6 10 6 5 8 .Approach:The idea is to push reverse Postorder traversal to a stack. Once we have the reversed postorder traversal in a stack, we can just pop all items one by one from the stack and print them; this order of printing will be in postorder because of the LIFO property of stacks. Now the question is, how to get reversed postorder elements in a stack - the second stack is used for this purpose. For example, in the following tree, we need to get 1, 3, 7, 6, 2, 5, 4 in a stack. If we take a closer look at this sequence, we can observe that this sequence is very similar to the preorder traversal. The only difference is that the right child is visited before left child, and therefore the sequence is “root right left” instead of “root left right”. So, we can do something like iterative preorder traversal with the following differences: a) Instead of printing an item, we push it to a stack. b) We push the left subtree before the right subtree.Follow the steps below to solve the problem:Push root to first stack.Loop until first stack is not emptyPop a node from first stack and push it to second stackPush left and right children of the popped node to first stackPrint contents of second stackConsider the following tree: Following are the steps to print Postorder traversal of the above tree using two stacks:1. Push 1 to first stack   First stack: 1   Second stack: empty2. Pop 1 from first stack and push it to second stack. Push left and right children of 1 to first stack   First stack: 2, 3   Second stack: 13. Pop 3 from first stack and push it to second stack. Push left and right children of 3 to first stack   First stack: 2, 6, 7   Second stack: 1, 34. Pop 7 from first stack and push it to second stack.   First stack: 2, 6   Second stack: 1, 3, 75. Pop 6 from first stack and push it to second stack.   First stack: 2   Second stack: 1, 3, 7, 66. Pop 2 from first stack and push it to second stack. Push left and right children of 2 to first stack   First stack: 4, 5   Second stack: 1, 3, 7, 6, 27. Pop 5 from first stack and push it to second stack.   First stack: 4   Second stack: 1, 3, 7, 6, 2, 58. Pop 4 from first stack and push it to second stack.   First stack: Empty   Second stack: 1, 3, 7, 6, 2, 5, 4The algorithm stops here since there are no more items in the first stack. Observe that the contents of second stack are in postorder manner. Print them. Below is the implementation of the above approach:
            C++

    // C++ program to o find the postorder 
// traversal using 2 Stacks
#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

// Function to do post-order traversal
// using two stacks iteratively
vector<int> postOrder(Node* root) {
    vector<int> result;
    if (root == nullptr) {
        return result;
    }

    // Create two stacks
    stack<Node*> stk1, stk2;

    // Push root to first stack
    stk1.push(root);
    Node* curr;

    // Run while first stack is not empty
    while (!stk1.empty()) {

        // Pop from s1 and push it to s2
        curr = stk1.top();
        stk1.pop();
        stk2.push(curr);

        // Push left and right children of the
        // popped node
        if (curr->left) {
            stk1.push(curr->left);
        }
        if (curr->right) {
            stk1.push(curr->right);
        }
    }

    // Collect all elements from second stack
    while (!stk2.empty()) {
        curr = stk2.top();
        stk2.pop();
        result.push_back(curr->data);
    }

    return result;
}

void printArray(const vector<int>& arr) {
    for (int data : arr) {
        cout << data << " ";
    }
    cout << endl;
}

int main() {

    // Representation of input binary tree:
    //           1
    //         /   \
    //        2     3
    //      /  \
    //     4    5
    Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);

    vector<int> result = postOrder(root);

    printArray(result);

    return 0;
}


            C

    // C program to find the postorder
// traversal using 2 stacks
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

// Stack structure for holding nodes
struct Stack {
    int top;
    int capacity;
    struct Node* array[100];
};

// Function to create a stack
struct Stack createStack(int capacity) {
    struct Stack stack;
    stack.top = -1;
    stack.capacity = capacity;
    return stack;
}

// Function to check if stack is empty
int isEmpty(struct Stack* stack) {
    return stack->top == -1;
}

// Function to push node onto the stack
void push(struct Stack* stack, struct Node* node) {
    stack->array[++stack->top] = node;
}

// Function to pop node from the stack
struct Node* pop(struct Stack* stack) {
    return stack->array[stack->top--];
}

// Function to perform postorder traversal 
// using two stacks
void postOrder(struct Node* root) {
    if (root == NULL) {
        return;
    }

    struct Stack stk1 = createStack(100); 
    struct Stack stk2 = createStack(100); 
    struct Node* curr;

    // Push root to first stack
    push(&stk1, root);

    // Loop while stk1 is not empty
    while (!isEmpty(&stk1)) {

        // Pop from stk1 and push it to stk2
        curr = pop(&stk1);
        push(&stk2, curr);

        // Push left and right children of popped node
        if (curr->left) {
            push(&stk1, curr->left);
        }
        if (curr->right) {
            push(&stk1, curr->right);
        }
    }

    // Print nodes in stk2 which gives postorder
    while (!isEmpty(&stk2)) {
        curr = pop(&stk2);
        printf("%d ", curr->data);
    }
}

struct Node* createNode(int x) {
    struct Node* node 
      = (struct Node*)malloc(sizeof(struct Node));
    node->data = x;
    node->left = node->right = NULL;
    return node;
}

int main() {

    // Representation of input binary tree:
    //           1
    //         /   \
    //        2     3
    //      /  \
    //     4    5
    struct Node* root = createNode(1);
    root->left = createNode(2);
    root->right = createNode(3);
    root->left->left = createNode(4);
    root->left->right = createNode(5);

    postOrder(root);

    return 0;
}


