            C#

    // C# program to o find the postorder 
// traversal using 2 Stacks
using System;
using System.Collections.Generic;

class Node {
    public int data;
    public Node left, right;

    public Node(int x) {
        data = x;
        left = right = null;
    }
}

class GfG {

    // Function to do post-order traversal 
    // using two stacks
    static List<int> postOrder(Node root) {
        List<int> result = new List<int>();
        if (root == null) {
            return result;
        }

        // Create two stacks
        Stack<Node> stk1 = new Stack<Node>();
        Stack<Node> stk2 = new Stack<Node>();

        // Push root to first stack
        stk1.Push(root);

        // Run while first stack is not empty
        while (stk1.Count > 0) {

            // Pop from stk1 and push it to stk2
            Node curr = stk1.Pop();
            stk2.Push(curr);

            // Push left and right children of 
            // the popped node
            if (curr.left != null) {
                stk1.Push(curr.left);
            }
            if (curr.right != null) {
                stk1.Push(curr.right);
            }
        }

        // Collect all elements from second stack
        while (stk2.Count > 0) {
            Node curr = stk2.Pop();
            result.Add(curr.data);
        }

        return result;
    }

    static void printArray(List<int> arr) {
        foreach (int data in arr) {
            Console.Write(data + " ");
        }
        Console.WriteLine();
    }

    static void Main(string[] args) {

        // Representation of input binary tree:
        //           1
        //         /   \
        //        2     3
        //      /  \
        //     4    5
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);

        List<int> result = postOrder(root);
        printArray(result);
    }
}


            JavaScript

    // JavaScript program to find the postorder 
// traversal using 2 Stacks
class Node {
    constructor(key) {
        this.key = key;
        this.left = null;
        this.right = null;
    }
}

// Function to perform postorder traversal 
// using two stacks
function postOrder(root) {
    const ans = [];
    if (!root) return ans;

    const stk1 = [root];  
    const stk2 = [];     

    // Loop while stk1 is not empty
    while (stk1.length > 0) {
        const node = stk1.pop();

         // Push node's key to stk2
        stk2.push(node.key); 

        // Push left and right children to stk1
        if (node.left) stk1.push(node.left);
        if (node.right) stk1.push(node.right);
    }

    // Collect nodes from s2 in postorder
    while (stk2.length > 0) {
        ans.push(stk2.pop());
    }

    return ans;
}

// Representation of input binary tree:
//           1
